import numpy as np

def slant_to_ground_flat(slant_ranges, sat_altitude_m):
    H = float(sat_altitude_m)
    arr = np.asarray(slant_ranges, dtype=np.float64)
    valid = arr >= H
    diff_sq = np.where(valid, arr * arr - H * H, 0.0)
    out = np.where(valid, np.sqrt(diff_sq), np.nan)
    if np.ndim(slant_ranges) == 0:
        return np.float64(out)
    return out
